const raw = $input.first().json;
const expected = $env.ANSER_WEBHOOK_TOKEN || '';
if (expected && ((raw.headers || {})['x-anser-token'] || '') !== expected) {
  return [{ json: { valid: false, error: 'Unauthorized' } }];
}
const b = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
if (!b.batch_code) return [{ json: { valid: false, error: 'Missing required field: batch_code' } }];
return [{ json: { valid: true, batch_code: String(b.batch_code), request_body: JSON.stringify({ batch_code: b.batch_code, cynarin_pct: b.cynarin_pct ?? 0, mold_cfu_g: b.mold_cfu_g ?? 0, pesticide_ok: b.pesticide_ok !== false, heavy_metal_ok: b.heavy_metal_ok !== false, tested_by: b.tested_by || null }) } }];

const d = $input.first().json;
const passed = d.status === 'passed';
let desc;
if (passed) {
  desc = 'Đạt toàn bộ chỉ tiêu dược liệu — **mở khóa cho phép bán**. Số phiếu kiểm nghiệm #' + d.test_id + ' đã gắn vào lô (phục vụ truy xuất GACP/QR).';
} else {
  desc = '**CHẶN XUẤT — tuyệt đối không bán lô này.**\nLý do: ' + (d.reasons || []).join('; ');
  if (d.investigate) {
    desc += '\n\n🔍 Điều tra nguồn gốc:\n• Lô NVL: ' + d.investigate.lot_code + '\n• Nông hộ/HTX: ' + d.investigate.farmer + '\n• Vùng trồng: ' + d.investigate.region_grown + '\n• Thu hái: ' + d.investigate.harvest_date;
  }
}
const notify_body = JSON.stringify({ channel: 'discord', title: (passed ? '🟢 KIỂM NGHIỆM ĐẠT — lô ' : '🔴 KIỂM NGHIỆM KHÔNG ĐẠT — lô ') + d.batch_code, color: passed ? 3066993 : 15158332, description: desc });
const resp = JSON.stringify({ status: d.status, batch_code: d.batch_code, test_id: d.test_id, sellable: d.sellable, reasons: d.reasons, investigate: d.investigate || null });
return [{ json: { notify_body, resp } }];
